thread::spawn(|| {
    // We only tap `FlagsChanged` (modifier key state changes), never `KeyDown`.
    // A ListenOnly event tap that observes modifier changes runs with the
    // Accessibility permission the app already requires. The moment a tap
    // observes key-down/key-up events, macOS additionally demands the
    // "Input Monitoring" permission ("receive keystrokes from any
    // application"). Since modifier-only hotkeys never need regular
    // keystrokes, restricting the tap to `FlagsChanged` keeps us on
    // Accessibility alone.
    let tap = CGEventTap::new(
        CGEventTapLocation::HID,
        CGEventTapPlacement::HeadInsertEventTap,
        CGEventTapOptions::ListenOnly,
        vec![CGEventType::FlagsChanged],
        |_proxy: CGEventTapProxy, event_type: CGEventType, event: &CGEvent| {
            if event_type == CGEventType::FlagsChanged {
                emit_system_key_event(event);
            }
            None
        },
    );

